private enum Active implements CameraSubjectBoundsResolver {
    INSTANCE;

    @Override
    public ExtensionResult<AABB> resolveBounds(Entity entity) {
      org.joml.Vector3d feetPosition = SableCompanion.INSTANCE.getFeetPos(entity, 0.0f);
      SableCompanion.INSTANCE.projectOutOfSubLevel(entity.level(), feetPosition);
      return ExtensionResult.handled(
          entity
              .getBoundingBox()
              .move(
                  feetPosition.x - entity.getX(),
                  feetPosition.y - entity.getY(),
                  feetPosition.z - entity.getZ()));
    }
  }

private enum Active implements EntityReferencePoseResolver {
    INSTANCE;

    @Override
    public ExtensionResult<EntityReferencePose> resolve(EntityReferencePoseContext context) {
      Entity entity = context.entity();
      float partialTick = context.partialTick();
      ClientSubLevelAccess subLevel = SableCompanion.INSTANCE.getContainingClient(entity);
      if (subLevel == null) {
        return ExtensionResult.pass();
      }
      Vec3 eye = SableCompanion.INSTANCE.getEyePositionInterpolated(entity, partialTick);
      var rotation = new Quaternionf(subLevel.renderPose(partialTick).orientation());
      return EntityReferencePose.tryCreate(new Vector3d(eye.x, eye.y, eye.z), rotation)
          .map(ExtensionResult::handled)
          .orElseGet(ExtensionResult::pass);
    }
  }

private enum Active implements MovementInputMapper {
    INSTANCE;

    @Override
    public ExtensionResult<MovementInput> map(LocalPlayer player, MovementIntent intent) {
      ClientSubLevelAccess subLevel = SableCompanion.INSTANCE.getContainingClient(player);
      if (subLevel == null) {
        return ExtensionResult.pass();
      }
      var pivotFromHeading =
          PerspectiveMath.eulerDegToQuat(0.0f, player.getYRot(), 0.0f, new Quaternionf());
      var worldFromInput =
          new Quaternionf(subLevel.renderPose(1.0f).orientation())
              .normalize()
              .mul(pivotFromHeading);
      return MinecraftMovementInputMapping.mapToBasis(intent, worldFromInput);
    }
  }

private enum Active implements SpatialQueryHitLocationResolver {
    INSTANCE;

    @Override
    public ExtensionResult<Vec3> resolveWorldLocation(Level level, HitResult hit) {
      if (hit.getType() == HitResult.Type.MISS) {
        return ExtensionResult.handled(hit.getLocation());
      }
      return ExtensionResult.handled(
          SableCompanion.INSTANCE.projectOutOfSubLevel(
              level, (net.minecraft.core.Position) hit.getLocation()));
    }
  }

